  SC.bench = function(){
    var tests = [['CPU một luồng','cpu',1840,[900,1600,2400]],['CPU đa luồng (8 luồng)','cpu',6120,[2800,7000,16000]],['SIMD (AVX2)','cpu',2210,[1100,2000,3200]],['Render 1 triệu đối tượng','gpu',58,[24,90,240],'FPS'],['Render 10 triệu đối tượng','gpu',9,[3,22,75],'FPS'],['Hatch dày','gpu',41,[18,70,180],'FPS'],['Chữ dày','gpu',47,[20,80,200],'FPS'],['Đọc đĩa','disk',512,[180,900,3200],'MB/s']];
    var dlg = TC.dialog({ id:'bench', title:'Kiểm tra hiệu năng máy', cmd:'TRIONBENCH', code:'UI-L11', w:700, body:'<div class="stack"><p class="muted" style="font-size:var(--fs-s)">Khoảng 1 phút. Nên đóng ứng dụng nặng khác. Kết quả dùng để đề xuất mức chất lượng đồ họa phù hợp.</p><div class="tblwrap"><table class="tbl" id="bn-t"><colgroup><col style="width:210px"><col style="width:110px"><col><col style="width:90px"></colgroup><thead><tr><th>Mục</th><th class="num">Điểm</th><th>So với máy tham chiếu</th><th>Trạng thái</th></tr></thead><tbody>' + tests.map(function(t, i){ return '<tr data-bt="' + i + '"><td>' + ic(t[1], 's12') + ' ' + t[0] + '</td><td class="num">—</td><td></td><td><span class="faint">Chờ</span></td></tr>'; }).join('') + '</tbody></table></div><div id="bn-res"></div><label class="chk"><input type="checkbox"> Gửi kết quả ẩn danh để TrionCAD tối ưu cho phần cứng phổ biến</label></div>', foot:'<button class="btn ghost" type="button" id="bn-hist">' + ic('clock') + 'Lịch sử đo (2)</button><span class="grow"></span><button class="btn ghost" type="button" data-x="cancel">Đóng</button><button class="btn primary" type="button" id="bn-go">Bắt đầu kiểm tra</button>' });
    $('#bn-hist', dlg.el).addEventListener('click', function(){ SC.textWindow('12/09/2026  LAPTOP-AN-KT  CPU 1 luồng 1.790 · đa luồng 5.980 · 1 triệu đối tượng 55 FPS\n02/07/2026  LAPTOP-AN-KT  CPU 1 luồng 1.760 · đa luồng 5.900 · 1 triệu đối tượng 41 FPS (driver cũ)', 'Lịch sử kiểm tra hiệu năng'); });
    $('#bn-go', dlg.el).addEventListener('click', function(){
      var btn = this; btn.disabled = true; var i = 0;
      (function next(){
        if (dlg.closed) return;
        if (i >= tests.length){ btn.disabled = false; btn.textContent = 'Kiểm tra lại'; $('#bn-res', dlg.el).innerHTML = '<div class="grp"><span class="gh">Đề xuất</span><p>Máy ở mức <b>văn phòng tầm trung</b>. Đề xuất: mức chất lượng <b>Cân bằng</b>, bật giới hạn khung hình khi chạy pin, LOD mức 3. Bản vẽ trên 2 triệu đối tượng vẫn mượt khi pan, zoom.</p><button class="btn sm primary" type="button" id="bn-apply" style="justify-self:start">Áp dụng cấu hình đề xuất</button></div>'; $('#bn-apply', dlg.el).addEventListener('click', function(){ TC.toast('Đã áp dụng mức chất lượng Cân bằng.', { log:false }); }); return; }
        var tr = $('[data-bt="' + i + '"]', dlg.el), t = tests[i]; tr.children[3].innerHTML = '<span class="hrow"><span class="spin"></span>Đang đo</span>';
        setTimeout(function(){ var max = t[3][2] * 1.05, pct = function(v){ return Math.min(100, v / max * 100); };
          tr.children[1].textContent = TC.n(t[2]) + (t[4] ? ' ' + t[4] : '');
          tr.children[2].innerHTML = '<div style="position:relative;height:12px;background:var(--c-active);border-radius:2px"><i style="position:absolute;left:0;top:0;bottom:0;width:' + pct(t[2]) + '%;background:var(--c-accent);border-radius:2px"></i>' + t[3].map(function(v, k){ return '<span title="' + ['Máy văn phòng cũ','Tầm trung','Máy trạm'][k] + ': ' + TC.n(v) + '" style="position:absolute;top:-3px;bottom:-3px;width:2px;left:' + pct(v) + '%;background:var(--c-text-2)"></span>'; }).join('') + '</div><div class="faint" style="font-size:9.5px;display:flex;justify-content:space-between;margin-top:2px"><span>văn phòng cũ</span><span>tầm trung</span><span>máy trạm</span></div>';
          tr.children[3].innerHTML = '<span class="ok">' + ic('okc', 's12') + ' Xong</span>'; i++; next(); }, 380);
      })();
    });
  };

